na-0" onclick="clickZonaDestino(0)" style="cursor: pointer;"> <rect x="20" y="20" width="190" height="155" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="2" stroke-dasharray="6,4"></rect> <text x="32" y="44" font-size="14" font-weight="900" fill="#7e22ce">GRUPO:</text> <!-- Letra u con vector flecha suprascrito exacto --> <g transform="translate(92, 30)"> <path d="M 0 2 L 11 2 M 8 0 L 11 2 L 8 4" fill="none" stroke="#7e22ce" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"></path> <text x="1" y="14" font-size="15" font-weight="900" fill="#7e22ce">u</text> </g> <line x1="40" y1="135" x2="160" y2="75" stroke="#9333ea" stroke-width="3.5" marker-end="url(#arrow-patron-0)"></line> </g> <!-- Caja 1: Azul Cian (v) --> <g id="drop-zona-1" onclick="clickZonaDestino(1)" style="cursor: pointer;"> <rect x="670" y="20" width="190" height="155" rx="8" fill="#f0f9ff" stroke="#0284c7" stroke-width="2" stroke-dasharray="6,4"></rect> <text x="682" y="44" font-size="14" font-weight="900" fill="#0369a1">GRUPO:</text> <g transform="translate(742, 30)"> <path d="M 0 2 L 11 2 M 8 0 L 11 2 L 8 4" fill="none" stroke="#0369a1" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"></path> <text x="1" y="14" font-size="15" font-weight="900" fill="#0369a1">v</text> </g> <line x1="820" y1="55" x2="700" y2="115" stroke="#0284c7" stroke-width="3.5" marker-end="url(#arrow-patron-1)"></line> </g> <!-- Caja 2: Naranja Cálido (w) --> <g id="drop-zona-2" onclick="clickZonaDestino(2)" style="cursor: pointer;"> <rect x="20" y="325" width="190" height="155" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="2" stroke-dasharray="6,4"></rect> <text x="32" y="349" font-size="14" font-weight="900" fill="#c2410c">GRUPO:</text> <g transform="translate(92, 335)"> <path d="M 0 2 L 13 2 M 10 0 L 13 2 L 10 4" fill="none" stroke="#c2410c" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"></path> <text x="0" y="14" font-size="15" font-weight="900" fill="#c2410c">w</text> </g> <line x1="50" y1="360" x2="150" y2="450" stroke="#ea580c" stroke-width="3.5" marker-end="url(#arrow-patron-2)"></line> </g> <!-- Caja 3: Verde Esmeralda (z) --> <g id="drop-zona-3" onclick="clickZonaDestino(3)" style="cursor: pointer;"> <rect x="670" y="325" width="190" height="155" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2" stroke-dasharray="6,4"></rect> <text x="682" y="349" font-size="14" font-weight="900" fill="#15803d">GRUPO:</text> <g transform="translate(742, 335)"> <path d="M 0 2 L 11 2 M 8 0 L 11 2 L 8 4" fill="none" stroke="#15803d" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"></path> <text x="1" y="14" font-size="15" font-weight="900" fill="#15803d">z</text> </g> <line x1="765" y1="455" x2="765" y2="350" stroke="#16a34a" stroke-width="3.5" marker-end="url(#arrow-patron-3)"></line> </g> <!-- Panel central de vectores no clasificados --> <rect x="235" y="35" width="410" height="430" rx="10" fill="#ffffff" fill-opacity="0.92" stroke="#cbd5e1" stroke-width="1.5"></rect> <text x="440" y="60" text-anchor="middle" font-size="12" font-weight="800" fill="#64748b" letter-spacing="0.5">VECTORES FIJOS POR CLASIFICAR</text> <!-- Capa de vectores móviles --> <g id="capa-vectores-moviles"></g> </svg></div>
