<style>
    .vector-g-cursor {
      cursor: grab;
      transition: filter 0.15s ease;
    }
    .vector-g-cursor:hover {
      filter: drop-shadow(0 2px 5px rgba(0,0,0,0.25));
    }
    .vector-g-cursor.activo {
      cursor: grabbing;
      filter: drop-shadow(0 0 8px #000dff);
