<div id="equipolentes-app" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"></div>
<p>
<script>
(function() {
  const CLASES = [
    { id: 0, dx: 120, dy: -60 }, // u (+120, -60)
    { id: 1, dx: -120, dy: 60 }, // v (-120, +60)
    { id: 2, dx: 100, dy: 90 },  // w (+100, +90)
    { id: 3, dx: 0, dy: -105 }   // z (0, -105)
  ];

  // 12 vectores distribuidos holgadamente para evitar superposiciones iniciales
  const VECTORES_BASE = [
    // 3 equipolentes a u (clase 0)
    { id: 0, clase: 0, origX: 250, origY: 145 },
    { id: 1, clase: 0, origX: 470, origY: 130 },
    { id: 2, clase: 0, origX: 370, origY: 215 },
    // 3 equipolentes a v (clase 1)
    { id: 3, clase: 1, origX: 400, origY: 85 },
    { id: 4, clase: 1, origX: 600, origY: 220 },
    { id: 5, clase: 1, origX: 430, origY: 275 },
    // 3 equipolentes a w (clase 2)
    { id: 6, clase: 2, origX: 250, origY: 200 },
    { id: 7, clase: 2, origX: 330, origY: 335 },
    { id: 8, clase: 2, origX: 510, origY: 335 },
    // 3 equipolentes a z (clase 3)
    { id: 9, clase: 3, origX: 275, origY: 345 },
    { id: 10, clase: 3, origX: 435, origY: 420 },
    { id: 11, clase: 3, origX: 590, origY: 410 }
  ];

  const CAJAS = [
    { xMin: 20, xMax: 210, yMin: 20, yMax: 175, centroX: 115, centroY: 97 },
    { xMin: 670, xMax: 860, yMin: 20, yMax: 175, centroX: 765, centroY: 97 },
    { xMin: 20, xMax: 210, yMin: 325, yMax: 480, centroX: 115, centroY: 402 },
    { xMin: 670, xMax: 860, yMin: 325, yMax: 480, centroX: 765, centroY: 402 }
  ];

  let vectores = [];
  let vectorSeleccionado = null;
  let arrastrando = false;
  let offsetMouse = { x: 0, y: 0 };

  function initVectores() {
    vectores = VECTORES_BASE.map(v => ({
      id: v.id,
      clase: v.clase,
      x: v.origX,
      y: v.origY,
      dx: CLASES[v.clase].dx,
      dy: CLASES[v.clase].dy,
      color: "#334155",
      asignadoACaja: null
    }));
    vectorSeleccionado = null;
    arrastrando = false;
    document.getElementById('fb-vectores-app').innerHTML = '';
    actualizarContador();
    dibujarVectores();
  }

  function getSVGPoint(e) {
    const svg = document.getElementById('svg-escena-vectores');
    const pt = svg.createSVGPoint();
    if (e.touches && e.touches.length > 0) {
      pt.x = e.touches[0].clientX;
      pt.y = e.touches[0].clientY;
    } else {
      pt.x = e.clientX;
      pt.y = e.clientY;
    }
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }

  function dibujarVectores() {
    const capa = document.getElementById('capa-vectores-moviles');
    capa.innerHTML = '';

    vectores.forEach((v, idx) => {
      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      g.setAttribute('class', 'vector-g-cursor' + (vectorSeleccionado === idx ? ' activo' : ''));
      g.setAttribute('id', 'vec-' + idx);

      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', v.x);
      line.setAttribute('y1', v.y);
      line.setAttribute('x2', v.x + v.dx);
      line.setAttribute('y2', v.y + v.dy);
      line.setAttribute('stroke', (vectorSeleccionado === idx) ? '#000dff' : v.color);
      line.setAttribute('stroke-width', '3');
      line.setAttribute('marker-end', 'url(#arrow-movil)');

      const origen = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      origen.setAttribute('cx', v.x);
      origen.setAttribute('cy', v.y);
      origen.setAttribute('r', '6');
      origen.setAttribute('fill', (vectorSeleccionado === idx) ? '#000dff' : '#0f172a');
      origen.setAttribute('stroke', '#ffffff');
      origen.setAttribute('stroke-width', '2');

      const clickArea = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      clickArea.setAttribute('x1', v.x);
      clickArea.setAttribute('y1', v.y);
      clickArea.setAttribute('x2', v.x + v.dx);
      clickArea.setAttribute('y2', v.y + v.dy);
      clickArea.setAttribute('stroke', 'transparent');
      clickArea.setAttribute('stroke-width', '22');

      g.appendChild(clickArea);
      g.appendChild(line);
      g.appendChild(origen);

      g.addEventListener('mousedown', (e) => iniciarArrastre(e, idx));
      g.addEventListener('touchstart', (e) => iniciarArrastre(e, idx), { passive: false });

      capa.appendChild(g);
    });
  }

  function iniciarArrastre(e, idx) {
    e.preventDefault();
    vectorSeleccionado = idx;
    arrastrando = true;
    const p = getSVGPoint(e);
    offsetMouse.x = p.x - vectores[idx].x;
    offsetMouse.y = p.y - vectores[idx].y;
    dibujarVectores();
  }

  function moverArrastre(e) {
    if (!arrastrando || vectorSeleccionado === null) return;
    e.preventDefault();
    const p = getSVGPoint(e);
    let v = vectores[vectorSeleccionado];
    v.x = Math.round(p.x - offsetMouse.x);
    v.y = Math.round(p.y - offsetMouse.y);
    dibujarVectores();
  }

  function soltarArrastre(e) {
    if (!arrastrando || vectorSeleccionado === null) return;
    arrastrando = false;
    let v = vectores[vectorSeleccionado];

    let midX = v.x + (v.dx / 2);
    let midY = v.y + (v.dy / 2);
    let cajaDestino = null;

    CAJAS.forEach((c, cIdx) => {
      if (midX >= c.xMin && midX <= c.xMax && midY >= c.yMin && midY <= c.yMax) {
        cajaDestino = cIdx;
      }
    });

    v.asignadoACaja = cajaDestino;
    actualizarContador();
    dibujarVectores();
  }

  window.clickZonaDestino = function(cajaIdx) {
    if (vectorSeleccionado !== null) {
      let v = vectores[vectorSeleccionado];
      v.asignadoACaja = cajaIdx;
      let c = CAJAS[cajaIdx];
      let offset = (v.id % 3) * 12 - 12;
      v.x = c.centroX - (v.dx / 2) + offset;
      v.y = c.centroY - (v.dy / 2) + offset;
      vectorSeleccionado = null;
      actualizarContador();
      dibujarVectores();
    }
  };

  function actualizarContador() {
    let cant = vectores.filter(v => v.asignadoACaja !== null).length;
    document.getElementById('contador-vectores-clasificados').textContent = `Clasificados: ${cant} de ${vectores.length}`;
  }

  window.reiniciarVectores = function() {
    initVectores();
  };

  window.comprobarVectores = function() {
    const fb = document.getElementById('fb-vectores-app');
    let faltan = vectores.filter(v => v.asignadoACaja === null).length;

    if (faltan > 0) {
      fb.style.color = '#dc2626';
      fb.innerHTML = `⚠️ Aún te faltan <strong>${faltan}</strong> vectores por colocar en sus cajas.`;
      return;
    }

    let todosBien = true;
    vectores.forEach(v => {
      if (v.asignadoACaja === v.clase) {
        v.color = '#16a34a';
      } else {
        v.color = '#dc2626';
        todosBien = false;
      }
    });

    dibujarVectores();

    if (todosBien) {
      fb.style.color = '#15803d';
      fb.innerHTML = '🎉 ¡Perfecto! Los 12 vectores fijos han sido clasificados correctamente en sus 4 vectores libres equipolentes.';
    } else {
      fb.style.color = '#b91c1c';
      fb.innerHTML = 'Revisa los vectores marcados en rojo: deben tener exactamente la misma pendiente (dirección) y el mismo sentido.';
    }
  };

  const svg = document.getElementById('svg-escena-vectores');
  svg.addEventListener('mousemove', moverArrastre);
  svg.addEventListener('mouseup', soltarArrastre);
  svg.addEventListener('touchmove', moverArrastre, { passive: false });
  svg.addEventListener('touchend', soltarArrastre);

  initVectores();
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

