<div style="background-color: #ffffff !important; border: 1px solid #cbd5e1 !important; border-radius: 8px !important; padding: 12px !important; text-align: center !important;"><svg id="svg-plano-rectas" viewbox="0 0 360 360" style="width: 100%; max-width: 380px; height: auto; display: block; margin: 0 auto; background: #ffffff;"> <defs> <!-- Malla secundaria de 1x1 unidades --> <pattern id="grid-sub" width="18" height="18" patternunits="userSpaceOnUse"> <path d="M 18 0 L 0 0 0 18" fill="none" stroke="#f1f5f9" stroke-width="1"></path> </pattern> <!-- Flecha para el vector director v --> <marker id="arrow-vec-director" viewbox="0 0 10 10" refx="7" refy="5" markerwidth="6" markerheight="6" orient="auto-start-reverse"> <path d="M 0 1 L 10 5 L 0 9 z" fill="#0284c7"></path> </marker> </defs> <rect width="360" height="360" fill="url(#grid-sub)"></rect> <!-- Ejes cartesianos principales centrados en (180, 180) --> <line x1="0" y1="180" x2="360" y2="180" stroke="#64748b" stroke-width="1.8"></line> <line x1="180" y1="0" x2="180" y2="360" stroke="#64748b" stroke-width="1.8"></line> <!-- Marcas y números clave --> <text x="350" y="174" font-size="11" font-weight="800" fill="#64748b">X</text> <text x="186" y="14" font-size="11" font-weight="800" fill="#64748b">Y</text> <!-- Capa dinámica de rectas, vector y puntos --> <g id="capa-dibujo-rectas"></g> </svg> <!-- Leyenda y Casilla de activación del vector director -->
<div style="display: flex; justify-content: center; align-items: center; gap: 14px; margin-top: 10px; font-size: 0.88rem; font-weight: bold; flex-wrap: wrap;"><span style="color: #0284c7; display: flex; align-items: center; gap: 4px;"> <span style="display: inline-block; width: 14px; height: 3px; background: #0284c7;"></span> Recta r </span> <span style="color: #ea580c; display: flex; align-items: center; gap: 4px;"> <span style="display: inline-block; width: 14px; height: 3px; background: #ea580c;"></span> Recta s </span> <label style="color: #0369a1; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; background: #f0f9ff; padding: 3px 8px; border-radius: 4px; border: 1px solid #bae6fd;"> <input type="checkbox" id="chk-ver-vector" onchange="toggleVectorDirector()" style="cursor: pointer;" /> <span>Ver vector <span style="display: inline-flex; align-items: center; vertical-align: middle;"><svg width="14" height="16" viewbox="0 0 14 16"><path d="M 1 3 L 11 3 M 8 0 L 11 3 L 8 6" fill="none" stroke="#0284c7" stroke-width="1.6"></path><text x="2" y="14" font-size="13" font-weight="900" fill="#0284c7">v</text></svg></span></span> </label></div>
