<option value="coincidentes">coincidentes</option>
</select><span id="ico-feedback-rectas" style="font-size: 1.4rem; font-weight: 900;"></span></div>
<div id="txt-msg-feedback" style="min-height: 24px; font-weight: 800; font-size: 0.96rem;"></div>
</div>
<!-- Panel explicativo paso a paso -->
<div id="panel-analisis-rectas" style="display: none; background-color: #ffffff !important; border-left: 5px solid #ea580c !important; border: 1px solid #fed7aa; border-radius: 8px !important; padding: 16px 18px !important; font-size: 0.94rem; line-height: 1.55; color: #334155;">
<div style="font-weight: 800; color: #9a3412; font-size: 1rem; margin-bottom: 8px;">💡 Justificación analítica (comparación de pendientes):</div>
<div id="txt-desarrollo-analitico"></div>
</div>
<!-- Botonera de acciones -->
<div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; padding-top: 6px;">
<div role="button" onclick="nuevoEjercicioRectas()" style="background-color: #ffffff !important; border: 2px solid #fdba74 !important; color: #c2410c !important; font-weight: 800 !important; font-size: 0.88rem !important; padding: 8px 16px !important; border-radius: 6px !important; cursor: pointer !important; text-transform: uppercase !important; line-height: 1 !important;" tabindex="0">Otras rectas</div>
<div role="button" onclick="comprobarRectas()" style="background-color: #f57c00 !important; border: 2px solid #ea580c !important; color: #ffffff !important; font-weight: 800 !important; font-size: 0.92rem !important; padding: 9px 24px !important; border-radius: 6px !important; cursor: pointer !important; box-shadow: 0 2px 6px rgba(245, 124, 0, 0.35) !important; text-transform: uppercase !important; line-height: 1 !important;" tabindex="0">Comprobar</div>
</div>
</div>
</div>
</div>
</div>
</div>
<style>
    .f-frac-recta {
      display: inline-flex;
      flex-direction: column;
      align-items: center;
      vertical-align: middle;
      line-height: 1;
      padding: 0 3px;
    }
    .f-frac-recta .fn, .f-frac-recta .fd {
      font-size: 1.05rem;
      font-weight: 800;
      color: #0f172a;
    }
    .f-frac-recta .fl {
      width: 100%;
      height: 2px;
      background: #0f172a;
      margin: 2px 0;
    }
    .svg-vec-inline {
      display: inline-flex;
      align-items: center;
      vertical-align: middle;
      line-height: 1;
    }
  </style>
<div id="pos-relativa-rectas-app" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"></div>
<p>
<script>
(function() {
  function mcd(a, b) {
    a = Math.abs(a); b = Math.abs(b);
    while (b) { let t = b; b = a % b; a = t; }
    return a;
  }

  function htmlFrac(num, den) {
    if (den === 1) return String(num);
    if (den === -1) return String(-num);
    let signo = '';
    if ((num < 0 && den > 0) || (num > 0 && den < 0)) signo = '−';
    let n = Math.abs(num);
    let d = Math.abs(den);
    return `${signo}<span class="f-frac-recta"><span class="fn">${n}</span><span class="fl"></span><span class="fd">${d}</span></span>`;
  }

  function htmlVectorV() {
    return `
      <span class="svg-vec-inline">
        <svg width="18" height="20" viewBox="0 0 18 20" style="overflow:visible;">
          <path d="M 2 4 L 14 4 M 11 1 L 14 4 L 11 7" fill="none" stroke="#0284c7" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
          <text x="3" y="17" font-size="15" font-weight="900" fill="#0284c7">v</text>
        </svg>
      </span>
    `;
  }

  let ejercicio = null;
  let rectasMostradas = false;

  function generarProblema() {
    const tipos = ['secantes', 'secantes', 'paralelas', 'coincidentes'];
    let tipo = tipos[Math.floor(Math.random() * tipos.length)];

    let P = { x: Math.floor(Math.random() * 11) - 5, y: Math.floor(Math.random() * 11) - 5 };
    let v = { x: 0, y: 0 };
    while (v.x === 0) {
      v.x = Math.floor(Math.random() * 7) - 3;
    }
    v.y = Math.floor(Math.random() * 7) - 3;

    let d_r = mcd(v.y, v.x);
    let mr_n = v.y / d_r;
    let mr_d = v.x / d_r;
    if (mr_d < 0) { mr_n = -mr_n; mr_d = -mr_d; }

    let ms_n, ms_d, N;

    if (tipo === 'secantes') {
      do {
        ms_d = Math.floor(Math.random() * 4) + 1;
        ms_n = Math.floor(Math.random() * 7) - 3;
      } while (mr_n * ms_d === ms_n * mr_d);
      N = { x: 0, y: Math.floor(Math.random() * 11) - 5 };
    } else if (tipo === 'paralelas') {
      ms_n = mr_n;
      ms_d = mr_d;
      let offset = (Math.random() < 0.5 ? 2 : -2);
      N = { x: 0, y: P.y - Math.round((mr_n / mr_d) * P.x) + offset };
      if (N.y > 6) N.y -= 4;
      if (N.y < -6) N.y += 4;
    } else {
      ms_n = mr_n;
      ms_d = mr_d;
      let k = (Math.random() < 0.5 ? 1 : -1);
      N = { x: P.x + k * v.x, y: P.y + k * v.y };
      if (Math.abs(N.x) > 7 || Math.abs(N.y) > 7) {
        N = { x: P.x, y: P.y };
      }
    }

    return {
      P: P,
      v: v,
      mr_n: mr_n,
      mr_d: mr_d,
      N: N,
      ms_n: ms_n,
      ms_d: ms_d,
      tipoCorrecto: tipo
    };
  }

  function toSvgX(x) { return 180 + x * 18; }
  function toSvgY(y) { return 180 - y * 18; }

  function dibujarEscena() {
    const capa = document.getElementById('capa-dibujo-rectas');
    capa.innerHTML = '';
    if (!ejercicio) return;

    let pX = toSvgX(ejercicio.P.x);
    let pY = toSvgY(ejercicio.P.y);
    let nX = toSvgX(ejercicio.N.x);
    let nY = toSvgY(ejercicio.N.y);

    let html = '';

    // Si se ha pedido mostrar las rectas completas (tras pulsar Comprobar)
    if (rectasMostradas) {
      let x1 = -12, y1 = ejercicio.P.y + (ejercicio.mr_n / ejercicio.mr_d) * (x1 - ejercicio.P.x);
      let x2 = 12,  y2 = ejercicio.P.y + (ejercicio.mr_n / ejercicio.mr_d) * (x2 - ejercicio.P.x);

      let x3 = -12, y3 = ejercicio.N.y + (ejercicio.ms_n / ejercicio.ms_d) * (x3 - ejercicio.N.x);
      let x4 = 12,  y4 = ejercicio.N.y + (ejercicio.ms_n / ejercicio.ms_d) * (x4 - ejercicio.N.x);

      if (ejercicio.tipoCorrecto === 'coincidentes') {
        html += `
          <line x1="${toSvgX(x1)}" y1="${toSvgY(y1)}" x2="${toSvgX(x2)}" y2="${toSvgY(y2)}" stroke="#0284c7" stroke-width="4"/>
          <line x1="${toSvgX(x1)}" y1="${toSvgY(y1)}" x2="${toSvgX(x2)}" y2="${toSvgY(y2)}" stroke="#ea580c" stroke-width="2" stroke-dasharray="6,6"/>
        `;
      } else {
        html += `
          <line x1="${toSvgX(x1)}" y1="${toSvgY(y1)}" x2="${toSvgX(x2)}" y2="${toSvgY(y2)}" stroke="#0284c7" stroke-width="2.5" opacity="0.9"/>
          <line x1="${toSvgX(x3)}" y1="${toSvgY(y3)}" x2="${toSvgX(x4)}" y2="${toSvgY(y4)}" stroke="#ea580c" stroke-width="2.5" opacity="0.9"/>
        `;
      }
    }

    // Vector director v anclado en el punto P (si la casilla está marcada)
    const verVector = document.getElementById('chk-ver-vector').checked;
    if (verVector) {
      let vEndX = toSvgX(ejercicio.P.x + ejercicio.v.x);
      let vEndY = toSvgY(ejercicio.P.y + ejercicio.v.y);
      html += `
        <line x1="${pX}" y1="${pY}" x2="${vEndX}" y2="${vEndY}" 
              stroke="#0284c7" stroke-width="3.5" stroke-linecap="round" 
              marker-end="url(#arrow-vec-director)"/>
        <g transform="translate(${(pX + vEndX)/2 + 6}, ${(pY + vEndY)/2 - 14})">
          <path d="M 0 2 L 10 2 M 7 0 L 10 2 L 7 4" fill="none" stroke="#0284c7" stroke-width="1.6"/>
          <text x="1" y="12" font-size="13" font-weight="900" fill="#0284c7">v</text>
        </g>
      `;
    }

    // Puntos P y N
    html += `
      <circle cx="${pX}" cy="${pY}" r="5" fill="#0284c7" stroke="#ffffff" stroke-width="1.5"/>
      <text x="${pX + 8}" y="${pY - 6}" font-size="12" font-weight="900" fill="#0284c7">P</text>

      <circle cx="${nX}" cy="${nY}" r="5" fill="#ea580c" stroke="#ffffff" stroke-width="1.5"/>
      <text x="${nX + 8}" y="${nY - 6}" font-size="12" font-weight="900" fill="#ea580c">N</text>
    `;

    capa.innerHTML = html;
  }

  window.toggleVectorDirector = function() {
    dibujarEscena();
  };

  window.nuevoEjercicioRectas = function() {
    ejercicio = generarProblema();
    rectasMostradas = false;

    let htmlP = `<strong>P ( ${ejercicio.P.x} , ${ejercicio.P.y} )</strong>`;
    let htmlN = `<strong>N ( ${ejercicio.N.x} , ${ejercicio.N.y} )</strong>`;
    let htmlV = `${htmlVectorV()} = <strong>( ${ejercicio.v.x} , ${ejercicio.v.y} )</strong>`;
    let htmlM = `<strong>m = ${htmlFrac(ejercicio.ms_n, ejercicio.ms_d)}</strong>`;

    document.getElementById('txt-enunciado-rectas').innerHTML = `
      Una recta <strong>r</strong> tiene como vector director ${htmlV} y pasa por el punto ${htmlP}, 
      otra recta <strong>s</strong> tiene pendiente ${htmlM} y pasa por el punto ${htmlN}. 
      <br><span style="color:#c2410c;">¿Cómo son estas rectas?</span>
    `;

    document.getElementById('sel-tipo-rectas').value = '';
    document.getElementById('ico-feedback-rectas').textContent = '';
    document.getElementById('txt-msg-feedback').innerHTML = '';
    document.getElementById('panel-analisis-rectas').style.display = 'none';

    dibujarEscena();
  };

  window.comprobarRectas = function() {
    let sel = document.getElementById('sel-tipo-rectas').value;
    let ico = document.getElementById('ico-feedback-rectas');
    let fb = document.getElementById('txt-msg-feedback');
    let panel = document.getElementById('panel-analisis-rectas');

    if (!sel) {
      fb.style.color = '#dc2626';
      fb.innerHTML = '⚠️ Selecciona una opción en el menú desplegable.';
      return;
    }

    rectasMostradas = true;
    dibujarEscena();

    let esCorrecto = (sel === ejercicio.tipoCorrecto);

    if (esCorrecto) {
      ico.style.color = '#16a34a';
      ico.textContent = '✓';
      fb.style.color = '#15803d';
      fb.innerHTML = `🎉 ¡Correcto! Las rectas son <strong>${ejercicio.tipoCorrecto}</strong>.`;
    } else {
      ico.style.color = '#dc2626';
      ico.textContent = '✗';
      fb.style.color = '#b91c1c';
      fb.innerHTML = `No es correcto. Eran <strong>${ejercicio.tipoCorrecto}</strong>. Observa el gráfico y la deducción analítica:`;
    }

    let fracMr = htmlFrac(ejercicio.mr_n, ejercicio.mr_d);
    let fracMs = htmlFrac(ejercicio.ms_n, ejercicio.ms_d);
    let textoAnalisis = `
      <ol style="margin: 0; padding-left: 20px;">
        <li style="margin-bottom: 6px;">
          <strong>Pendiente de r:</strong> A partir de su vector director \\(\\vec{v} = (v_1, v_2) = (${ejercicio.v.x}, ${ejercicio.v.y})\\):
          <br>\\(m_r = \\dfrac{v_2}{v_1} = \\dfrac{${ejercicio.v.y}}{${ejercicio.v.x}} = \\) ${fracMr}.
        </li>
        <li style="margin-bottom: 6px;">
          <strong>Pendiente de s:</strong> Nos dan directamente su pendiente: \\(m_s = \\) ${fracMs}.
        </li>
    `;

    if (ejercicio.tipoCorrecto === 'secantes') {
      textoAnalisis += `
        <li>
          <strong>Conclusión:</strong> Como \\(m_r \\neq m_s\\) (${fracMr} \\(\\neq\\) ${fracMs}), las rectas tienen distinta dirección y, por tanto, son <strong>secantes</strong> (se cortan en un punto).
        </li>
      </ol>`;
    } else if (ejercicio.tipoCorrecto === 'paralelas') {
      textoAnalisis += `
        <li>
          <strong>Conclusión:</strong> Tienen la misma pendiente \\(m_r = m_s = \\) ${fracMr}, por lo que son paralelas o coincidentes. Comprobando si el punto \\(N(${ejercicio.N.x}, ${ejercicio.N.y})\\) pertenece a la recta \\(r\\), vemos que no la cumple. Por tanto, son <strong>paralelas estrictas</strong>.
        </li>
      </ol>`;
    } else {
      textoAnalisis += `
        <li>
          <strong>Conclusión:</strong> Tienen la misma pendiente \\(m_r = m_s = \\) ${fracMr} y comparten puntos (el punto \\(N\\) satisface la ecuación de \\(r\\)). Por consiguiente, son <strong>coincidentes</strong> (la misma recta).
        </li>
      </ol>`;
    }

    document.getElementById('txt-desarrollo-analitico').innerHTML = textoAnalisis;
    panel.style.display = 'block';

    if (window.MathJax && window.MathJax.typesetPromise) {
      window.MathJax.typesetPromise();
    }
  };

  nuevoEjercicioRectas();
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
